-- ============================================================
-- DB-21: test 侧 varchar/numeric 安全加宽对齐 prod（16 列）
--
-- 范围：仅 topems_test（prod 机同实例），严禁在 topems_prod 执行。
-- 依据：prod 列宽/精度 >= test 的 13 个 varchar(含 varchar→text) + 3 个 numeric 项。
-- 实测：无 FK/视图/生成列依赖；加宽不会截断或丢精度。
-- 幂等：DO 块按当前 format_type 精确匹配 test 旧类型后执行。
-- 未纳入：13 项 prod 更短（test 更宽）不在加宽范围；数值族/契约类只分类不执行。
-- ============================================================

SET lock_timeout = '5s';

DO $m$ BEGIN IF EXISTS (SELECT 1 FROM pg_attribute a JOIN pg_class t ON t.oid=a.attrelid JOIN pg_namespace n ON n.oid=t.relnamespace WHERE n.nspname='ehs' AND t.relname='qa_ehs_environment_monitors' AND a.attname='location' AND NOT a.attisdropped AND format_type(a.atttypid,a.atttypmod)='character varying(200)') THEN ALTER TABLE ehs.qa_ehs_environment_monitors ALTER COLUMN location TYPE character varying(256); END IF; END $m$;
DO $m$ BEGIN IF EXISTS (SELECT 1 FROM pg_attribute a JOIN pg_class t ON t.oid=a.attrelid JOIN pg_namespace n ON n.oid=t.relnamespace WHERE n.nspname='ehs' AND t.relname='qa_ehs_environment_monitors' AND a.attname='monitor_type' AND NOT a.attisdropped AND format_type(a.atttypid,a.atttypmod)='character varying(50)') THEN ALTER TABLE ehs.qa_ehs_environment_monitors ALTER COLUMN monitor_type TYPE character varying(64); END IF; END $m$;
DO $m$ BEGIN IF EXISTS (SELECT 1 FROM pg_attribute a JOIN pg_class t ON t.oid=a.attrelid JOIN pg_namespace n ON n.oid=t.relnamespace WHERE n.nspname='ehs' AND t.relname='qa_ehs_environment_monitors' AND a.attname='name' AND NOT a.attisdropped AND format_type(a.atttypid,a.atttypmod)='character varying(200)') THEN ALTER TABLE ehs.qa_ehs_environment_monitors ALTER COLUMN name TYPE character varying(256); END IF; END $m$;
DO $m$ BEGIN IF EXISTS (SELECT 1 FROM pg_attribute a JOIN pg_class t ON t.oid=a.attrelid JOIN pg_namespace n ON n.oid=t.relnamespace WHERE n.nspname='ehs' AND t.relname='qa_ehs_environment_monitors' AND a.attname='status' AND NOT a.attisdropped AND format_type(a.atttypid,a.atttypmod)='character varying(20)') THEN ALTER TABLE ehs.qa_ehs_environment_monitors ALTER COLUMN status TYPE character varying(32); END IF; END $m$;
DO $m$ BEGIN IF EXISTS (SELECT 1 FROM pg_attribute a JOIN pg_class t ON t.oid=a.attrelid JOIN pg_namespace n ON n.oid=t.relnamespace WHERE n.nspname='ehs' AND t.relname='qa_ehs_environment_monitors' AND a.attname='unit' AND NOT a.attisdropped AND format_type(a.atttypid,a.atttypmod)='character varying(50)') THEN ALTER TABLE ehs.qa_ehs_environment_monitors ALTER COLUMN unit TYPE character varying(64); END IF; END $m$;
DO $m$ BEGIN IF EXISTS (SELECT 1 FROM pg_attribute a JOIN pg_class t ON t.oid=a.attrelid JOIN pg_namespace n ON n.oid=t.relnamespace WHERE n.nspname='ehs' AND t.relname='qa_ehs_environmental_regulations' AND a.attname='created_by' AND NOT a.attisdropped AND format_type(a.atttypid,a.atttypmod)='character varying(64)') THEN ALTER TABLE ehs.qa_ehs_environmental_regulations ALTER COLUMN created_by TYPE character varying(128); END IF; END $m$;
DO $m$ BEGIN IF EXISTS (SELECT 1 FROM pg_attribute a JOIN pg_class t ON t.oid=a.attrelid JOIN pg_namespace n ON n.oid=t.relnamespace WHERE n.nspname='ehs' AND t.relname='qa_ehs_hazardous_materials' AND a.attname='current_stock' AND NOT a.attisdropped AND format_type(a.atttypid,a.atttypmod)='numeric(12,2)') THEN ALTER TABLE ehs.qa_ehs_hazardous_materials ALTER COLUMN current_stock TYPE numeric(15,3); END IF; END $m$;
DO $m$ BEGIN IF EXISTS (SELECT 1 FROM pg_attribute a JOIN pg_class t ON t.oid=a.attrelid JOIN pg_namespace n ON n.oid=t.relnamespace WHERE n.nspname='ehs' AND t.relname='qa_ehs_hazardous_materials' AND a.attname='max_stock' AND NOT a.attisdropped AND format_type(a.atttypid,a.atttypmod)='numeric(12,2)') THEN ALTER TABLE ehs.qa_ehs_hazardous_materials ALTER COLUMN max_stock TYPE numeric(15,3); END IF; END $m$;
DO $m$ BEGIN IF EXISTS (SELECT 1 FROM pg_attribute a JOIN pg_class t ON t.oid=a.attrelid JOIN pg_namespace n ON n.oid=t.relnamespace WHERE n.nspname='ehs' AND t.relname='qa_ehs_hazardous_materials' AND a.attname='min_stock' AND NOT a.attisdropped AND format_type(a.atttypid,a.atttypmod)='numeric(12,2)') THEN ALTER TABLE ehs.qa_ehs_hazardous_materials ALTER COLUMN min_stock TYPE numeric(15,3); END IF; END $m$;
DO $m$ BEGIN IF EXISTS (SELECT 1 FROM pg_attribute a JOIN pg_class t ON t.oid=a.attrelid JOIN pg_namespace n ON n.oid=t.relnamespace WHERE n.nspname='ehs' AND t.relname='qa_ehs_hazards' AND a.attname='location' AND NOT a.attisdropped AND format_type(a.atttypid,a.atttypmod)='character varying(128)') THEN ALTER TABLE ehs.qa_ehs_hazards ALTER COLUMN location TYPE character varying(256); END IF; END $m$;
DO $m$ BEGIN IF EXISTS (SELECT 1 FROM pg_attribute a JOIN pg_class t ON t.oid=a.attrelid JOIN pg_namespace n ON n.oid=t.relnamespace WHERE n.nspname='ehs' AND t.relname='qa_ehs_hazards' AND a.attname='reported_by' AND NOT a.attisdropped AND format_type(a.atttypid,a.atttypmod)='character varying(64)') THEN ALTER TABLE ehs.qa_ehs_hazards ALTER COLUMN reported_by TYPE character varying(128); END IF; END $m$;
DO $m$ BEGIN IF EXISTS (SELECT 1 FROM pg_attribute a JOIN pg_class t ON t.oid=a.attrelid JOIN pg_namespace n ON n.oid=t.relnamespace WHERE n.nspname='ehs' AND t.relname='qa_ehs_hazards' AND a.attname='source' AND NOT a.attisdropped AND format_type(a.atttypid,a.atttypmod)='character varying(64)') THEN ALTER TABLE ehs.qa_ehs_hazards ALTER COLUMN source TYPE character varying(128); END IF; END $m$;
DO $m$ BEGIN IF EXISTS (SELECT 1 FROM pg_attribute a JOIN pg_class t ON t.oid=a.attrelid JOIN pg_namespace n ON n.oid=t.relnamespace WHERE n.nspname='iam' AND t.relname='permission_audit_logs' AND a.attname='action' AND NOT a.attisdropped AND format_type(a.atttypid,a.atttypmod)='character varying(32)') THEN ALTER TABLE iam.permission_audit_logs ALTER COLUMN action TYPE character varying(64); END IF; END $m$;
DO $m$ BEGIN IF EXISTS (SELECT 1 FROM pg_attribute a JOIN pg_class t ON t.oid=a.attrelid JOIN pg_namespace n ON n.oid=t.relnamespace WHERE n.nspname='pm' AND t.relname='projects' AND a.attname='cost_center_name' AND NOT a.attisdropped AND format_type(a.atttypid,a.atttypmod)='character varying(255)') THEN ALTER TABLE pm.projects ALTER COLUMN cost_center_name TYPE character varying(256); END IF; END $m$;
DO $m$ BEGIN IF EXISTS (SELECT 1 FROM pg_attribute a JOIN pg_class t ON t.oid=a.attrelid JOIN pg_namespace n ON n.oid=t.relnamespace WHERE n.nspname='pm' AND t.relname='projects' AND a.attname='name_en' AND NOT a.attisdropped AND format_type(a.atttypid,a.atttypmod)='character varying(255)') THEN ALTER TABLE pm.projects ALTER COLUMN name_en TYPE character varying(500); END IF; END $m$;
DO $m$ BEGIN IF EXISTS (SELECT 1 FROM pg_attribute a JOIN pg_class t ON t.oid=a.attrelid JOIN pg_namespace n ON n.oid=t.relnamespace WHERE n.nspname='public' AND t.relname='core_workflow_tasks' AND a.attname='priority' AND NOT a.attisdropped AND format_type(a.atttypid,a.atttypmod)='character varying') THEN ALTER TABLE public.core_workflow_tasks ALTER COLUMN priority TYPE text USING priority::text; END IF; END $m$;
